def reconcile(desired, actual):
    create = sorted(set(desired) - set(actual))
    delete = sorted(set(actual) - set(desired))
    update = sorted(
        key for key in set(desired) & set(actual)
        if desired[key] != actual[key]
    )
    return {"create": create, "update": update, "delete": delete}
```

