def changed_paths(before, after):
    """Return sorted dot-separated paths for additions, removals, or unequal leaves.

    Recurses only where BOTH values are dicts. Lists and other values are
    compared atomically. If a key is entirely added or removed, only the
    parent path is returned (not its children).
    """
    paths = set()
    _diff(before, after, "", paths)
    return sorted(paths)


def _diff(before, after, prefix, paths):
    for key in set(before) | set(after):
        path = f"{prefix}.{key}" if prefix else key

        if key not in before:
            paths.add(path)
        elif key not in after:
            paths.add(path)
        else:
            bv = before[key]
            av = after[key]
            if isinstance(bv, dict) and isinstance(av, dict):
                _diff(bv, av, path, paths)
            elif bv != av:
                paths.add(path)
```

