import copy


def merge(base, overlay):
    """Recursively merge two JSON-like dictionaries.

    Overlay values replace base values. If both values for a key are
    dicts, they are merged recursively. A None value in overlay simply
    replaces the base value (it does not delete the key). The result is
    a new structure with no aliasing or mutation of the inputs.
    """
    result = {}

    for key in base:
        if key in overlay:
            base_val = base[key]
            overlay_val = overlay[key]
            if isinstance(base_val, dict) and isinstance(overlay_val, dict):
                result[key] = merge(base_val, overlay_val)
            else:
                result[key] = copy.deepcopy(overlay_val)
        else:
            result[key] = copy.deepcopy(base[key])

    for key in overlay:
        if key not in base:
            result[key] = copy.deepcopy(overlay[key])

    return result
```

