def pack(items, max_bytes):
    if max_bytes < 1:
        raise ValueError("max_bytes must be >= 1")

    result = []
    current_batch = []
    current_sum = 0

    for item in items:
        byte_len = len(item.encode("utf-8"))
        if byte_len > max_bytes:
            raise ValueError(
                f"Item with {byte_len} bytes does not fit within {max_bytes} bytes"
            )
        if current_sum + byte_len <= max_bytes:
            current_batch.append(item)
            current_sum += byte_len
        else:
            result.append(current_batch)
            current_batch = [item]
            current_sum = byte_len

    if current_batch:
        result.append(current_batch)

    return result
```

